"""The book's Glossary and List of Symbols, generated by `registry build
--glossary/--notation` from the accepted units' `scope.md` glossaries
(#1138).

Most of these pin the layout with an identity converter, so they run on
a host with no pandoc; the ones that need the real conversion skip
without it, as the render tests do.
"""

import pytest

from chitragupta import dossier, registry
from chitragupta.registry import _pages
from chitragupta.render_output import _pandoc
from chitragupta.render_output._errors import MissingBinary
from tests.conftest import pandoc_available

# conftest's `signed_book` reads this module's BOOK_SPEC as the outline.
from tests.test_registry import BOOK_SPEC, accept  # noqa: F401


@pytest.fixture
def book(signed_book):
    return signed_book


def identity(texts):
    return list(texts)


def pages(book):
    return _pages.render(registry.build(book), identity)


# --- the Glossary --------------------------------------------------------


def test_terms_are_alphabetical_whatever_order_the_units_hold_them(book):
    accept(
        book, "ch-model", "", glossary="- **Model** -- a description.\n- **Baseline** -- a value."
    )
    glossary, _ = pages(book)
    assert glossary.index("Baseline") < glossary.index("Model")


def test_one_definition_prints_inline_with_its_chapter(book):
    accept(book, "ch-model", "", glossary="- **Model** -- a description.")
    glossary, _ = pages(book)
    assert "\\item[{Model}] a description. (\\Cref{ch-model})" in glossary
    assert "\\chapter*{Glossary}" in glossary
    assert "\\addcontentsline{toc}{chapter}{Glossary}" in glossary


def test_several_definitions_print_numbered_in_outline_order(book):
    accept(book, "ch-data", "", glossary="- **Digital twin (DT)** -- a DO paired with a PT.")
    accept(book, "ch-model", "", glossary="- **Digital twin** -- software that keeps a model.")
    glossary, _ = pages(book)
    first = glossary.index("software that keeps a model. (\\Cref{ch-model})")
    second = glossary.index("a DO paired with a PT. (\\Cref{ch-data})")
    assert "\\begin{enumerate}" in glossary
    assert first < second
    assert "\\item[{Digital twin}]" in glossary


def test_an_identical_definition_prints_once_with_every_chapter(book):
    accept(book, "ch-model", "", glossary="- **Sensor** -- a component.")
    accept(book, "ch-data", "", glossary="- **Sensor** -- a component.")
    glossary, _ = pages(book)
    assert "\\item[{Sensor}] a component. (\\Cref{ch-model}, \\Cref{ch-data})" in glossary
    assert "enumerate" not in glossary


def test_a_terms_symbol_is_shown_after_its_name(book):
    accept(book, "ch-model", "", glossary="- **Baseline** (`M_0`) -- a value.")
    glossary, _ = pages(book)
    assert "\\item[{Baseline (`M_0`)}]" in glossary


def test_a_bare_symbol_is_in_the_list_of_symbols_and_not_the_glossary(book):
    accept(book, "ch-model", "", glossary="- **`x_k`** -- the state at step k.")
    glossary, notation = pages(book)
    assert glossary is None
    assert "`x_k` & the state at step k. & \\Cref{ch-model} \\\\" in notation


def test_no_terms_means_no_pages(book):
    accept(book, "ch-model", "", glossary="")
    assert pages(book) == (None, None)


# --- the List of Symbols -------------------------------------------------


def test_one_meaning_in_several_chapters_is_one_row(book):
    accept(book, "ch-model", "", glossary="- **Real-time factor** (`RTF`) -- a ratio.")
    accept(book, "ch-data", "", glossary="- **real-time factor** (`RTF`) -- a ratio.")
    _, notation = pages(book)
    assert notation.count("`RTF` &") == 1
    assert "`RTF` & Real-time factor & \\Cref{ch-model}, \\Cref{ch-data} \\\\" in notation
    assert "\\chapter*{List of Symbols}" in notation


def test_different_meanings_are_one_row_each(book):
    accept(book, "ch-model", "", glossary="- **Gain** (`k`) -- the gain.")
    accept(book, "ch-data", "", glossary="- **Rate constant** (`k`) -- the rate.")
    _, notation = pages(book)
    assert "`k` & Gain & \\Cref{ch-model}" in notation
    assert "`k` & Rate constant & \\Cref{ch-data}" in notation


def test_greek_follows_latin_and_anything_else_comes_last(book):
    accept(
        book,
        "ch-model",
        "",
        glossary="- **Parameter** (`theta`) -- p.\n- **Dose** (`V`) -- d.\n"
        "- **Count** (`2n`) -- c.\n- **Mean** (`mu_k`) -- m.\n- **Time** (`t`) -- t.",
    )
    _, notation = pages(book)
    order = [notation.index(f"`{s}` &") for s in ("t", "V", "mu_k", "theta", "2n")]
    assert order == sorted(order)


def test_a_mapped_symbol_is_typeset_with_its_units_math(book):
    path = book / "ch-model.md"
    math = dossier.dossier_dir(path) / "math.md"
    math.parent.mkdir(parents=True, exist_ok=True)
    math.write_text("| ASCII | LaTeX |\n| --- | --- |\n| `M_0` | `M_{0}` |\n")
    accept(book, "ch-model", "", glossary="- **Baseline** (`M_0`) -- above `M_0` here.")
    glossary, notation = pages(book)
    assert "$M_{0}$ & Baseline" in notation
    assert "\\item[{Baseline ($M_{0}$)}] above $M_{0}$ here." in glossary


@pytest.mark.skipif(not pandoc_available, reason="pandoc not installed")
def test_the_real_conversion_escapes_and_typesets(book):
    accept(book, "ch-model", "", glossary="- **Share** (`p`) -- 50% of **all** runs & more.")
    glossary, notation = _pages.render(registry.build(book), _pandoc.markdown_to_latex)
    assert "50\\% of \\textbf{all} runs \\& more." in glossary
    assert "\\texttt{p} & Share" in notation


# --- `registry build --glossary/--notation` -----------------------------


def build(book, tmp_path, *extra):
    glossary, notation = tmp_path / "glossary.tex", tmp_path / "notation.tex"
    args = ["build", str(book), "--glossary", str(glossary), "--notation", str(notation)]
    return registry.main(args + list(extra)), glossary, notation


@pytest.fixture
def no_pandoc_needed(monkeypatch):
    monkeypatch.setattr("chitragupta.registry._cli.markdown_to_latex", identity)


def test_build_writes_both_pages(book, tmp_path, no_pandoc_needed, capsys):
    accept(book, "ch-model", "", glossary="- **Baseline** (`M_0`) -- a value.")
    code, glossary, notation = build(book, tmp_path)
    assert code == 0
    assert "Baseline" in glossary.read_text(encoding="utf-8")
    assert "`M_0`" in notation.read_text(encoding="utf-8")
    assert f"Wrote {glossary}." in capsys.readouterr().out


def test_rebuilding_unchanged_units_writes_the_same_bytes(book, tmp_path, no_pandoc_needed):
    accept(book, "ch-model", "", glossary="- **Baseline** (`M_0`) -- a value.")
    _, glossary, notation = build(book, tmp_path)
    first = glossary.read_bytes(), notation.read_bytes()
    build(book, tmp_path)
    assert (glossary.read_bytes(), notation.read_bytes()) == first


def test_an_off_format_bullet_refuses_and_leaves_an_earlier_page_alone(
    book, tmp_path, no_pandoc_needed, capsys
):
    accept(book, "ch-model", "", glossary="- **Model** -- a description.")
    _, glossary, notation = build(book, tmp_path)
    before = glossary.read_text(encoding="utf-8")
    accept(book, "ch-model", "Edited.\n", glossary="- **Residual**: the difference.")
    code, _, _ = build(book, tmp_path)
    err = capsys.readouterr().err
    assert code == 1
    assert "[glossary] ch-model scope.md:" in err and "no page written" in err
    assert glossary.read_text(encoding="utf-8") == before
    assert (registry.registry_dir(book) / "terms.md").is_file()


def test_nothing_to_print_writes_no_page_and_says_so(book, tmp_path, no_pandoc_needed, capsys):
    accept(book, "ch-model", "", glossary="- **Model** -- a description.")
    code, glossary, notation = build(book, tmp_path)
    assert code == 0
    assert glossary.is_file() and not notation.exists()
    assert "No symbol entries" in capsys.readouterr().out


def test_only_the_page_asked_for_is_written(book, tmp_path, no_pandoc_needed):
    accept(book, "ch-model", "", glossary="- **Baseline** (`M_0`) -- a value.")
    glossary = tmp_path / "glossary.tex"
    assert registry.main(["build", str(book), "--glossary", str(glossary)]) == 0
    assert glossary.is_file() and not (tmp_path / "notation.tex").exists()


def test_a_missing_pandoc_refuses_with_the_render_layers_error(book, tmp_path, monkeypatch, capsys):
    def missing(texts):
        raise MissingBinary("'pandoc' is not on PATH.")

    monkeypatch.setattr("chitragupta.registry._cli.markdown_to_latex", missing)
    accept(book, "ch-model", "", glossary="- **Model** -- a description.")
    code, glossary, _ = build(book, tmp_path)
    assert code == 1
    assert "[missing-binary]" in capsys.readouterr().err
    assert not glossary.exists()


def test_check_still_exits_zero_on_the_bullets_build_refuses(book, capsys):
    accept(book, "ch-model", "", glossary="- **Residual**: the difference.")
    capsys.readouterr()
    assert registry.main(["check", str(book)]) == 0
    assert "[glossary]" in capsys.readouterr().out


def test_a_refused_page_leaves_no_temporary_file(book, tmp_path, monkeypatch):
    """`write` renames into place, so a failure mid-write leaves the
    directory as it was."""

    def failing_replace(src, dst):
        raise OSError("disk full")

    monkeypatch.setattr(_pages.os, "replace", failing_replace)
    with pytest.raises(OSError):
        _pages.write(tmp_path / "rendered" / "glossary.tex", "text")
    assert list((tmp_path / "rendered").iterdir()) == []
